package bolonhaemilano;
import java.util.*;
public class Menu {
 private final Scanner scanner=new Scanner(System.in);
 private final Mercado mercado=new Mercado(); private final Agricultura agricultura=new Agricultura(); private final Governo governo=new Governo(); private final Construcoes construcoes=new Construcoes(); private final Nobreza nobreza=new Nobreza();
 private Partida partida; private boolean emExecucao=true;
 private int lerInteiro(){while(scanner.hasNextLine()){try{return Integer.parseInt(scanner.nextLine().trim());}catch(NumberFormatException e){System.out.println("Digite um número inteiro.");}}emExecucao=false;return 0;}
 private int perguntar(String s){System.out.println(s);return lerInteiro();}
 private String nome(String pergunta,String padrao){System.out.println(pergunta);if(!scanner.hasNextLine()){emExecucao=false;return padrao;}String s=scanner.nextLine().trim();return s.isEmpty()?padrao:s;}
 private boolean exigirJogoEmAndamento(){if(partida!=null)return true;System.out.println("Nenhum jogo em andamento.");return false;}
 private void iniciarNovoJogo(){int n=perguntar("Quantos jogadores (1 a 4)?");if(n<1||n>4){System.out.println("Quantidade inválida.");return;}String[] nomes={"Bolonha","Milano","Florença","Veneza"};List<Cidade> cs=new ArrayList<>();for(int i=0;i<n;i++){Jogador j=new Jogador(nome("Nome do jogador "+(i+1)+":","Jogador "+(i+1)));cs.add(new Cidade(nome("Nome da cidade:",nomes[i]),j));}partida=new Partida(cs);}
 public void executar(){while(emExecucao){System.out.println("\n=== BOLONHA E MILANO ===");if(partida!=null)System.out.println("Ano "+partida.getAnoAtual()+" | Vez: "+partida.getCidadeAtual().getDono().getNome());System.out.println("1 Novo jogo\n2 Ver status\n3 Mercado\n4 Agricultura\n5 Governo\n6 Construções\n7 Encerrar turno\n8 Classificação\n9 Sobre\n0 Sair");int op=lerInteiro();if(op==0){emExecucao=false;continue;}if(op==1){iniciarNovoJogo();continue;}if(op==9){System.out.println("Governe sua cidade medieval e alcance o título de Rei/Rainha até 1410.");continue;}if(op<2||op>8){System.out.println("Opção inválida.");continue;}if(!exigirJogoEmAndamento())continue;Cidade c=partida.getCidadeAtual();switch(op){case 2:c.exibirStatus();break;case 3:abrirMercado(c);break;case 4:abrirAgricultura(c);break;case 5:abrirGoverno(c);break;case 6:abrirConstrucoes(c);break;case 7:if(partida.encerrarTurno()){System.out.println("Ano encerrado.");classificacao();}if(partida.terminou()){Cidade v=partida.getVencedor();System.out.println("Vencedor: "+v.getDono().getNome()+" ("+v.getNome()+")");partida=null;}break;case 8:classificacao();break;default:break;}}}
 private void resultado(boolean ok){System.out.println(ok?"Operação realizada.":"Operação recusada: valor inválido ou recursos insuficientes.");}
 private void abrirMercado(Cidade c){while(emExecucao){int op=perguntar("1 Comprar grãos (2) | 2 Vender grãos (2) | 3 Comprar terras (1) | 4 Vender terras (1) | 0 Voltar");if(op==0)return;if(op<1||op>4){System.out.println("Opção inválida.");continue;}int n=perguntar("Quantidade:");switch(op){case 1:resultado(mercado.comprarGraos(c,n));break;case 2:resultado(mercado.venderGraos(c,n));break;case 3:resultado(mercado.comprarTerras(c,n));break;case 4:resultado(mercado.venderTerras(c,n));break;default:break;}}}
 private void abrirAgricultura(Cidade c){while(emExecucao){int op=perguntar("1 Colher | 2 Distribuir alimentos | 0 Voltar");if(op==0)return;if(op==1){if(c.isColheu())System.out.println("Colheita já realizada neste ano.");else System.out.println("Grãos produzidos: "+agricultura.processarColheita(c));}else if(op==2)resultado(agricultura.distribuirAlimentos(c,perguntar("Percentual (20 a 80):")));else System.out.println("Opção inválida.");}}
 private void abrirGoverno(Cidade c){while(emExecucao){int op=perguntar("1 Arrecadar impostos | 2 Definir taxa | 3 Definir justiça | 0 Voltar");if(op==0)return;if(op==1){if(c.isArrecadou())System.out.println("Impostos já arrecadados neste ano.");else System.out.println("Florins arrecadados: "+governo.arrecadarImpostos(c));}else if(op==2)resultado(governo.definirTaxaImposto(c,perguntar("Taxa (0 a 50):")));else if(op==3){int j=perguntar("1 Justa | 2 Moderada | 3 Severa");resultado(j>=1&&j<=3&&governo.definirNivelJustica(c,new String[]{"Justa","Moderada","Severa"}[j-1]));}else System.out.println("Opção inválida.");}}
 private void abrirConstrucoes(Cidade c){while(emExecucao){int op=perguntar("1 Recrutar soldados (5 florins + 1 servo) | 2 Construir (20 florins) | 0 Voltar");if(op==0)return;if(op==1)resultado(construcoes.recrutarSoldados(c,perguntar("Quantidade:")));else if(op==2)resultado(construcoes.construir(c,perguntar("Quantidade:")));else System.out.println("Opção inválida.");}}
 private void classificacao(){List<Cidade> cs=new ArrayList<>(partida.getCidades());cs.sort(Comparator.comparingInt((Cidade c)->c.getDono().getNivel()).thenComparingInt(nobreza::calcularPrestigio).reversed());for(Cidade c:cs)System.out.printf("%s - %s | %d pontos | %s%n",c.getNome(),c.getDono().getTitulo(),nobreza.calcularPrestigio(c),c.getDono().ehMonarca()?"Título máximo":"Próxima meta: "+nobreza.proximoPrestigio(c));}
}